WITH latest AS (SELECT *, RANK() OVER (PARTITION BY merchant, txn_type ORDER BY txn_time DESC NULLS LAST) AS row_num FROM transactions QUALIFY row_num = 1) SELECT merchant, DATE_TRUNC('MONTH', txn_time) AS activity_month, txn_type, COUNT(*) FILTER (WHERE txn_type = 'DEBIT') AS debit_rows, SUM(CASE WHEN merchant = 'Amazon' THEN amount ELSE 0 END) AS amazon_amount, GROUPING(merchant) AS grouping_level FROM latest GROUP BY ROLLUP (merchant, DATE_TRUNC('MONTH', txn_time), txn_type) ORDER BY amazon_amount DESC NULLS LAST
